<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {exportTable,type Table} from '../api';import {useLab} from '../store';
const emit=defineEmits<{'row-select':[number]}>();const scroll=ref<HTMLElement>();
const props=withDefaults(defineProps<{table:Table,title?:string,compact?:boolean,highlightRows?:number[],highlightColumns?:number[],tone?:string,teaching?:boolean,diffRows?:number[]}>(),{title:'查询结果',compact:false,highlightRows:()=>[],highlightColumns:()=>[],tone:'active',teaching:false,diffRows:()=>[]});const lab=useLab();const filter=ref('');const sort=ref(-1);const direction=ref(1);const top=ref(0);const rowHeight=32;const selected=ref('');
const rows=computed(()=>{let rows=props.table.rows.map((cells,index)=>({cells,index}));if(filter.value)rows=rows.filter(r=>r.cells.some(c=>('value'in c?String(c.value):'NULL').toLowerCase().includes(filter.value.toLowerCase())));if(sort.value>=0)rows.sort((a,b)=>{const x=a.cells[sort.value],y=b.cells[sort.value];const value=(v:typeof x)=>'value'in v?String(v.value):'';return direction.value*value(x).localeCompare(value(y),'zh-CN',{numeric:true});});return rows;});
watch(()=>props.highlightRows,ids=>{if(props.teaching&&ids.length&&scroll.value){const n=ids[0];const target=Math.max(0,(n-2)*rowHeight);if(n*rowHeight<scroll.value.scrollTop||n*rowHeight>scroll.value.scrollTop+150){scroll.value.scrollTop=target;top.value=target;}}});
function columnLabel(column:string){if(!props.teaching)return column;return column.replace('__sqlk_truth','谓词真值').replace('__sqlk_group','分组编号').replace('__group_rows','组内行数').replace('__sqlk_division','除法条件').replace('__sqlk_acc:','累计 ')}
const start=computed(()=>Math.max(0,Math.floor(top.value/rowHeight)-3));const visible=computed(()=>rows.value.slice(start.value,start.value+35));watch(()=>props.table,()=>{top.value=0;sort.value=-1;filter.value=''});function setSort(i:number){direction.value=sort.value===i?-direction.value:1;sort.value=i;}async function copy(s:string){try{await navigator.clipboard.writeText(s);lab.log('值已复制');}catch{selected.value=s;}}
</script>
<template><section class="result-table" :class="{compact}"><div class="table-tools"><strong>{{title}}</strong><span class="muted">{{rows.length}} 行 · {{table.columns.length}} 列</span><input v-if="!teaching" v-model="filter" placeholder="筛选当前结果…" aria-label="筛选结果"><button title="导出 CSV" @click="exportTable(table,'csv').catch(lab.fail)">CSV ↗</button><button title="导出 JSON" @click="exportTable(table,'json').catch(lab.fail)">JSON ↗</button></div><div v-if="table.truncated" class="notice warning">结果仅为预览，已达行数／大小限制，不能据此判题。</div><div ref="scroll" class="table-scroll" @scroll="top=($event.target as HTMLElement).scrollTop"><table><thead><tr><th class="row-number">#</th><th v-for="(column,i) in table.columns" :key="i" @click="!teaching&&setSort(i)">{{columnLabel(column)}} <span v-if="sort===i">{{direction===1?'↑':'↓'}}</span></th></tr></thead><tbody><tr v-if="start" :style="{height:`${start*rowHeight}px`}"><td :colspan="table.columns.length+1" /></tr><tr v-for="row in visible" :key="row.index" :data-row="row.index" :class="[{['row-'+tone]:highlightRows.includes(row.index),'row-diff':diffRows.includes(row.index)}]" @click="emit('row-select',row.index)"><td class="row-number">{{row.index+1}}</td><td v-for="(cell,i) in row.cells" :key="i" :class="{'cell-emphasis':highlightRows.includes(row.index)&&highlightColumns.includes(i)}" :title="'value'in cell?String(cell.value):'NULL'" @dblclick="copy('value'in cell?String(cell.value):'NULL')"><span v-if="cell.kind==='null'" class="null-value">NULL</span><span v-else-if="cell.kind==='binary'" class="muted">BLOB {{cell.value}}</span><span v-else>{{cell.value===''?'（空字符串）':cell.value}}</span></td></tr><tr v-if="rows.length>start+visible.length" :style="{height:`${(rows.length-start-visible.length)*rowHeight}px`}"><td :colspan="table.columns.length+1" /></tr></tbody></table><div v-if="!rows.length" class="empty">{{table.columns.length?'查询完成，结果为空集。':'该语句没有结果集。'}}</div></div><textarea v-if="selected" v-model="selected" readonly aria-label="复制值" /></section></template>
